return items.map(item => {
  const j = item.json || {};
  const title = j.title || j.name || j.query || '';
  const description = j.contentSnippet || j.content || j.description || '';
  const sourceUrl = j.link || j.guid || 'https://trends.google.com/trending?geo=BR';
  const publishedAt = j.isoDate || j.pubDate || new Date().toISOString();

  return {
    json: {
      trend_title: String(title).trim(),
      trend_description: String(description || '').slice(0, 4000),
      source_url: sourceUrl,
      observed_at: new Date(publishedAt).toISOString()
    }
  };
}).filter(i => i.json.trend_title);

return items.map((item, index) => {
  const base = $('Normalizar tendência').itemMatching(index).json;
  const raw = item.json?.output ?? item.json?.text ?? item.json?.response ?? item.json;

  let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

  let ai;
  try {
    ai = JSON.parse(text);
  } catch (e) {
    ai = {
      relevant: false,
      entity_type: 'other',
      name: base.trend_title,
      author_name: null,
      categories: [],
      reason: 'Não foi possível interpretar a resposta da IA.',
      content_opportunity: '',
      site_segment: null,
      confidence: 0
    };
  }

  return {
    json: {
      ...base,
      relevant: ai.relevant === true,
      entity_type: ai.entity_type || 'other',
      entity_name: ai.name || base.trend_title,
      author_name: ai.author_name || null,
      categories: Array.isArray(ai.categories) ? ai.categories : [],
      reason: ai.reason || '',
      content_opportunity: ai.content_opportunity || '',
      site_segment: ai.site_segment || null,
      confidence: Number(ai.confidence || 0)
    }
  };
});

return items.map((item, index) => {
  const base = $('É editorial?').itemMatching(index).json;
  const gb = item.json || {};
  const first = Array.isArray(gb.items) && gb.items.length ? gb.items[0] : null;
  const info = first?.volumeInfo || {};
  const ids = Array.isArray(info.industryIdentifiers) ? info.industryIdentifiers : [];
  const isbn13 = ids.find(x => x.type === 'ISBN_13')?.identifier || null;

  const googleCategories = Array.isArray(info.categories) ? info.categories : [];
  const categories = [...new Set([...(base.categories || []), ...googleCategories])];

  const canonicalTitle =
    base.entity_type === 'book' && first?.volumeInfo?.title
      ? first.volumeInfo.title
      : base.entity_name;

  const canonicalAuthor =
    Array.isArray(info.authors) && info.authors.length
      ? info.authors.join(', ')
      : base.author_name;

  const keyName = String(canonicalTitle || base.entity_name).trim().toLowerCase();
  const datePart = String(base.observed_at || new Date().toISOString()).slice(0, 10);

  return {
    json: {
      ...base,
      entity_name: canonicalTitle,
      author_name: canonicalAuthor || null,
      google_books_found: !!first,
      google_books_id: first?.id || null,
      isbn13,
      publisher: info.publisher || null,
      image_url: info.imageLinks?.thumbnail || info.imageLinks?.smallThumbnail || null,
      categories,
      dedupe_key: `google_trends|${keyName}|${datePart}`,
      metadata: {
        trend_description: base.trend_description,
        google_books: first ? {
          id: first.id || null,
          publishedDate: info.publishedDate || null,
          description: info.description || null,
          infoLink: info.infoLink || null
        } : {}
      }
    }
  };
});
